        "log_shipper.py": "\"\"\"Ships application logs to the central store in batches. Keeps a checkpoint so restarts resume.\"\"\"\nimport json, os, time\n\nCHECKPOINT = os.environ.get(\"CHECKPOINT_FILE\", \"/state/checkpoint\")\nBATCH_BYTES = 1 << 20\n\ndef log(**kw):\n    print(json.dumps({\"svc\": \"log-shipper\", \"time\": time.strftime(\"%Y-%m-%dT%H:%M:%S%z\"), **kw}), flush=True)\n\ndef read_batch(offset):\n    return os.urandom(BATCH_BYTES)  # stands in for a chunk of the spooled log files\n\nif not os.path.exists(CHECKPOINT):\n    with open(CHECKPOINT, \"w\") as f:\n        f.write(\"0\")\n    log(msg=\"no checkpoint found, replaying full backlog\")\n    pending, offset = [], 0\n    while True:  # the whole backlog is buffered before the first flush\n        pending.append(read_batch(offset))\n        offset += BATCH_BYTES\nlog(msg=\"resuming from checkpoint\", mode=\"incremental\")\nwhile True:\n    time.sleep(30)\n    log(msg=\"shipped\", batches=1)\n",
